export PYTHONDONTWRITEBYTECODE=1
cleanup() { /usr/bin/umount -R "$PWD/mnt" 2>/dev/null; /usr/sbin/dmsetup remove_all 2>/dev/null; /usr/sbin/losetup -D 2>/dev/null; /usr/bin/rm -f ./*.img ./*.txt; }
trap cleanup EXIT
mapk=(); mapv=()
reg() { mapk+=("$1"); mapv+=("$2"); }
norm() { local s i; s=$(< "$1"); for i in "${!mapk[@]}"; do s=${s//"${mapk[i]}"/${mapv[i]}}; done; while [[ $s == *'  '* ]]; do s=${s//'  '/ }; done; printf '%s\n' "$s"; }
normv() { local s=$1 i; for i in "${!mapk[@]}"; do s=${s//"${mapk[i]}"/${mapv[i]}}; done; printf '%s' "$s"; }
at() { REPLY=$(/usr/sbin/losetup -fP --show "$1") || echo "losetup failed: $1" >&2; local n=${REPLY#/dev/} p i; for p in /sys/block/$n/${n}p*; do [[ -e $p ]] || continue; for ((i=0;i<50;i++)); do [[ -b /dev/${p##*/} ]] && break; read -t 0.1 <> <(:) || :; done; done; }
MK=/usr/sbin/mke2fs

